function defaultObjectLayerRecord(index = 0, options = {}) {
  return {
    id: String(options.id || (index === 0 ? "layer-artwork" : makeId("layer"))),
    name: String(options.name || (index === 0 ? "Artwork" : `Layer ${index + 1}`)).trim().slice(0, 80) || `Layer ${index + 1}`,
    visible: options.visible !== false,
    locked: options.locked === true,
    collapsed: options.collapsed === true,
    color: String(options.color || OBJECT_LAYER_COLORS[index % OBJECT_LAYER_COLORS.length])
  };
}

function normalizeObjectLayerState(value = {}) {
  const seen = new Set();
  const rawLayers = Array.isArray(value?.layers) ? value.layers : [];
  const layers = rawLayers.map((raw, index) => defaultObjectLayerRecord(index, raw)).filter((layer) => {
    if (!layer.id || seen.has(layer.id)) return false;
    seen.add(layer.id);
    return true;
  });
  if (!layers.length) layers.push(defaultObjectLayerRecord(0));
  const requested = String(value?.activeLayerId || value?.active_layer_id || "");
  return {
    schema: OBJECT_LAYER_SCHEMA,
    activeLayerId: layers.some((layer) => layer.id === requested) ? requested : layers.at(-1).id,
    layers
  };
}

function activeObjectLayerState() {
  const page = activeDeckPage();
  if (!page) return normalizeObjectLayerState();
  page.objectLayers = normalizeObjectLayerState(page.objectLayers);
  return page.objectLayers;
}

function objectLayerById(layerId, layerState = activeObjectLayerState()) {
  return layerState.layers.find((layer) => layer.id === String(layerId || "")) || null;
}

function activeObjectLayer(layerState = activeObjectLayerState()) {
  return objectLayerById(layerState.activeLayerId, layerState) || layerState.layers.at(-1) || null;
}

function topLevelLayerObject(object) {
  let current = object || null;
  while (current?.group && !isActiveSelectionObject(current.group)) current = current.group;
  return current;
}

function objectLayerId(object, layerState = activeObjectLayerState()) {
  const root = topLevelLayerObject(object);
  const requested = String(root?.figureStudioLayerId || "");
  return objectLayerById(requested, layerState)?.id || layerState.layers[0]?.id || "layer-artwork";
}

function assignObjectToActiveLayer(object, options = {}) {
  if (!object || !isFigureObject(object)) return object;
  const layerState = activeObjectLayerState();
  const requested = String(options.layerId || object.figureStudioLayerId || "");
  const layer = objectLayerById(requested, layerState)
    || (options.legacy ? layerState.layers[0] : activeObjectLayer(layerState));
  if (layer) object.set?.({ figureStudioLayerId: layer.id });
  return object;
}

function setActiveObjects(objects) {
  const focused = (objects || []).at(-1) || null;
  const focusedLayerId = focused ? objectLayerId(focused) : "";
  if (isGroupIsolationActive()) {
    const isolated = (objects || []).filter((object) => objectIsWithinGroup(object, activeIsolationGroup()));
    if (isolated.length) {
      selectIsolatedObjects(isolated, { sync: true });
      return;
    }
  }
  canvas.discardActiveObject();
  if (!objects.length) {
    canvas.requestRenderAll();
    syncUi();
    return;
  }
  if (objects.length === 1) {
    canvas.setActiveObject(objects[0]);
  } else {
    const selection = new fabricRef.ActiveSelection(objects, { canvas });
    configureActiveSelection(selection);
    canvas.setActiveObject(selection);
  }
  if (focusedLayerId && objectLayerById(focusedLayerId)) activeObjectLayerState().activeLayerId = focusedLayerId;
  canvas.requestRenderAll();
  syncUi();
}

function configureActiveSelection(selection) {
  if (!isActiveSelectionObject(selection)) return selection;
  const transformGuard = numericTransformSelectionGuard(selection.getObjects());
  const transformable = transformGuard.status === "ok";
  selection.set({
    selectable: true,
    evented: true,
    hasControls: transformable,
    hasBorders: true,
    lockMovementX: !transformable,
    lockMovementY: !transformable,
    lockScalingX: !transformable,
    lockScalingY: !transformable,
    lockRotation: !transformable
  });
  return selection;
}

function selectedTopLevelObjects() {
  if (isGroupIsolationActive()) {
    const isolated = isolatedSelectedObjects();
    if (isolated.length) return isolated;
  }
  const active = canvas.getActiveObject();
  if (!active) return [];
  if (isActiveSelectionObject(active)) return active.getObjects();
  return [active];
}

function configureIsolationGroup(group) {
  if (!isGroupObject(group)) return false;
  if (!group.figureStudioIsolationMeta) {
    group.figureStudioIsolationMeta = {
      interactive: group.interactive === true,
      subTargetCheck: group.subTargetCheck === true,
      objectCaching: group.objectCaching !== false
    };
  }
  // Figure Tool owns child targeting, multi-selection, and transform
  // overlays in Isolation Mode. Fabric's interactive-group selection mutates
  // nested group membership when a second child is clicked, so keep vendor
  // sub-target activation off and resolve the child from the scene point.
  group.set({ interactive: false, subTargetCheck: false, objectCaching: false });
  groupChildren(group).forEach(ensureIsolationObjectIdentity);
  group.dirty = true;
  group.setCoords?.();
  return true;
}

function restoreIsolationGroupSettings(group) {
  const original = group?.figureStudioIsolationMeta;
  if (!group || !original) return false;
  group.set({
    interactive: original.interactive === true,
    subTargetCheck: original.subTargetCheck === true,
    objectCaching: original.objectCaching !== false
  });
  delete group.figureStudioIsolationMeta;
  group.dirty = true;
  group.setCoords?.();
  return true;
}

function isolatedSelectedObjects() {
  if (!isGroupIsolationActive()) return [];
  const activeGroup = activeIsolationGroup();
  const stored = Array.isArray(groupIsolation.selectedObjects) && groupIsolation.selectedObjects.length
    ? groupIsolation.selectedObjects
    : groupIsolation.selected ? [groupIsolation.selected] : [];
  const valid = uniqueObjects(stored).filter((object) => (
    object
    && objectIsWithinGroup(object, activeGroup)
    && object.visible !== false
    && !object.locked
  ));
  if (valid.length !== stored.length) {
    groupIsolation.selectedObjects = valid;
    groupIsolation.selected = valid.at(-1) || null;
  }
  return valid;
}

function selectableIsolationChildren(group = activeIsolationGroup()) {
  return groupChildren(group).filter((child) => child && child.visible !== false && !child.locked && !child.pdfPageFrame);
}

function captureGroupIsolationHistoryState() {
  if (!isGroupIsolationActive()) return null;
  return {
    pathIds: groupIsolation.path.map((group) => String(group?.figureId || "")).filter(Boolean),
    selectedIds: isolatedSelectedObjects().map((object) => String(object?.figureId || "")).filter(Boolean)
  };
}

function restoreGroupIsolationHistoryState(saved) {
  const pathIds = Array.isArray(saved?.pathIds) ? saved.pathIds.map((id) => String(id || "")).filter(Boolean) : [];
  if (!pathIds.length) return false;
  const path = [];
  for (const id of pathIds) {
    const group = findNestedObjectByFigureId(id);
    const expectedParent = path.at(-1) || null;
    if (
      !isGroupObject(group)
      || (expectedParent ? group.group !== expectedParent : !(canvas?.getObjects?.() || []).includes(group))
    ) break;
    configureIsolationGroup(group);
    path.push(group);
  }
  if (!path.length) return false;
  groupIsolation = { path, selected: null, selectedObjects: [], guardingSelection: false };
  state.tool = "directSelect";
  syncToolMode();
  const activeGroup = path.at(-1);
  const selected = (Array.isArray(saved?.selectedIds) ? saved.selectedIds : [])
    .map((id) => findNestedObjectByFigureId(id))
    .filter((object) => object && objectIsWithinGroup(object, activeGroup) && object.visible !== false && !object.locked);
  selectIsolatedObjects(selected.length ? selected : selectableIsolationChildren(activeGroup).slice(0, 1), {
    sync: false,
    toast: false,
    revealInLayers: false
  });
  renderGroupIsolationBar();
  requestSelectionOverlayRender();
  return true;
}

function selectIsolatedObjects(objects, options = {}) {
  const activeGroup = activeIsolationGroup();
  if (!activeGroup) return false;
  const selected = uniqueObjects(objects)
    .filter((object) => object && objectIsWithinGroup(object, activeGroup) && object.visible !== false && !object.locked);
  selected.forEach((object, index) => ensureIsolationObjectIdentity(object, index));
  groupIsolation.selectedObjects = selected;
  groupIsolation.selected = selected.at(-1) || null;
  selectionOverlayRenderOnly = true;
  window.queueMicrotask(() => { selectionOverlayRenderOnly = false; });
  canvas.discardActiveObject();
  if (groupIsolation.selected) canvas.setActiveObject(groupIsolation.selected);
  requestSelectionOverlayRender();
  if (options.sync !== false) {
    syncSelectionStatusOnly();
    scheduleSelectionUiSync();
  }
  if (options.toast && selected.length > 1) showToast(`${selected.length} group objects selected`);
  else if (options.toast && selected[0]) showToast(`Selected ${selected[0].name || humanizeType(selected[0].figureType || selected[0].type)}`);
  else hideToast();
  if (options.revealInLayers !== false) revealEditableSvgSelectionInLayers(selected.at(-1));
  return selected.length > 0;
}

function pathNodeEditObjects() {
  const seen = new Set();
  const objects = [];
  [pathNodeEdit.object, ...(Array.isArray(pathNodeEdit.objects) ? pathNodeEdit.objects : [])].forEach((object) => {
    if (!object || !canUsePathPointEditing(object)) return;
    const id = pathEditObjectId(object);
    if (seen.has(id)) return;
    seen.add(id);
    objects.push(object);
  });
  return objects;
}

function selectedPathHandleRefs() {
  const selectedRefs = Array.isArray(pathNodeEdit.selectedHandles) && pathNodeEdit.selectedHandles.length
    ? pathNodeEdit.selectedHandles
    : pathNodeEdit.selected ? [pathNodeEdit.selected] : [];
  return selectedRefs.map((ref) => ({ ...ref, objectId: ref.objectId || pathEditObjectId(pathNodeEdit.object) }));
}

function captureDirectSelectionHistoryState() {
  if (state.tool !== "directSelect" || !pathNodeEdit.object) return null;
  const stripHandle = (ref) => ({
    objectId: String(ref?.objectId || pathEditObjectId(pathNodeEdit.object)),
    nodeId: String(ref?.nodeId || ""),
    commandIndex: Number(ref?.commandIndex),
    handleType: String(ref?.handleType || "endpoint")
  });
  const saved = {
    primaryObjectId: pathEditObjectId(pathNodeEdit.object),
    objectIds: pathNodeEditObjects().map(pathEditObjectId),
    selectedHandles: selectedPathHandleRefs().map(stripHandle),
    selectedSegment: pathNodeEdit.selectedSegment ? {
      objectId: String(pathNodeEdit.selectedSegment.objectId || ""),
      contourIndex: Number(pathNodeEdit.selectedSegment.contourIndex),
      startNodeId: String(pathNodeEdit.selectedSegment.startNodeId || ""),
      endNodeId: String(pathNodeEdit.selectedSegment.endNodeId || ""),
      endCommandIndex: Number(pathNodeEdit.selectedSegment.endCommandIndex)
    } : null
  };
  const page = densePdfPageForObject(pathNodeEdit.object);
  if (page && saved.objectIds.length === 1 && !saved.selectedSegment
      && densePdfApi().objectById(page, saved.primaryObjectId) === pathNodeEdit.object
      && canUsePathPointEditing(pathNodeEdit.object)) {
    const descriptor = densePdfApi().descriptor(page);
    saved.densePage = { figureId: page.figureId, assetId: descriptor.assetId,
      source: structuredClone(descriptor.source), topology: pathNodeEdit.object.path.map((command) => [command[0], command.length]) };
  }
  return saved;
}

function syncLineVectorSelectionChrome() {
  if (!canvas) return;
  const freeTransform = state.tool === "freeTransform";
  const directSelection = state.tool === "directSelect";
  const active = canvas.getActiveObject?.();
  if (isActiveSelectionObject(active)) {
    const showGroupBounds = !directSelection;
    active.set({
      selectable: !directSelection,
      evented: !directSelection,
      hasControls: showGroupBounds,
      hasBorders: showGroupBounds,
      padding: directSelection ? 0 : Number(active.padding || 0),
      cornerSize: directSelection ? 0 : Number(active.cornerSize || 5),
      borderColor: directSelection ? "rgba(0,0,0,0)" : "rgba(15, 139, 141, 0.75)",
      lockMovementX: directSelection,
      lockMovementY: directSelection,
      lockScalingX: directSelection,
      lockScalingY: directSelection,
      lockRotation: directSelection
    });
    active.setCoords?.();
  }
  selectedTopLevelObjects().filter(isLineVectorObject).forEach((object) => {
    object.set({ hasControls: freeTransform && !object.locked, hasBorders: freeTransform && !object.locked });
  });
  selectedTopLevelObjects().filter(isSmartConnectorObject).forEach((object) => {
    const meta = normalizeSmartConnectorMeta(object.smartConnectorMeta);
    const movable = !meta.start.objectId && !meta.end.objectId && !directSelection && !object.locked;
    object.set({
      hasControls: false,
      hasBorders: !directSelection,
      lockMovementX: !movable,
      lockMovementY: !movable,
      lockScalingX: true,
      lockScalingY: true,
      lockRotation: true
    });
  });
  canvas.requestRenderAll?.();
}

function runCanvasLoadCompletion(resolve, reject, restore) {
  try {
    restore();
    resolve();
  } catch (error) {
    reject(error);
  }
}

async function loadCanvasJson(json, options = {}) {
  const editablePdf = globalThis.FigureStudioPdfEditableImport;
  if (editablePdf) await editablePdf.registerFonts(editablePdf.fontsInWorkspace(state.pdfSources));
  nativePdfLifecycleEpoch += 1;
  const denseReplacement = densePdfApi()?.beginSceneReplacement(canvas);
  let loadFailed = false;
  return new Promise((resolve, reject) => {
    try {
      const missing = Array.isArray(options.missing) ? options.missing : [];
      const compacted = json && typeof json === "object"
        ? fileFormatApi().compactSharedGroupImportMetadata(json)
        : json;
      const hydrated = compacted && typeof compacted === "object"
        ? hydrateArtifactRefPlaceholders(JSON.parse(JSON.stringify(compacted)), missing)
        : compacted;
      const finishLoad = () => runCanvasLoadCompletion(resolve, reject, completeLoadedCanvasScene);
      const result = canvas.loadFromJSON(hydrated, undefined, denseReplacement ? { signal: denseReplacement.signal } : undefined);
      if (result && typeof result.then === "function") {
        result.then(finishLoad).catch(reject);
      } else {
        canvas.loadFromJSON(hydrated, finishLoad);
      }
    } catch (error) {
      reject(error);
    }
  }).catch((error) => { loadFailed = true;throw error; }).finally(() => {
    if (denseReplacement) { try { densePdfApi().finishSceneReplacement(denseReplacement); } catch (error) { if (!loadFailed) throw error; } }
  });
}

async function loadStaticCanvasJson(staticCanvas, json) {
  // Fabric 6+ returns a Promise and reserves the second argument for an
  // object reviver. Passing a completion callback there resolves on the
  // first object, which can leave an offscreen export canvas empty.
  const majorVersion = Number.parseInt(String(fabricRef?.version || "0").split(".")[0], 10);
  if (majorVersion >= 6) {
    await staticCanvas.loadFromJSON(json);
    return staticCanvas;
  }
  await new Promise((resolve, reject) => {
    try { staticCanvas.loadFromJSON(json, resolve); }
    catch (error) { reject(error); }
  });
  return staticCanvas;
}

async function renderPresentationSlide() {
  const pages = state.deck?.pages || [];
  const page = pages[presentationState.pageIndex];
  const staticCanvas = presentationCanvasForQa();
  if (!page || !staticCanvas) return false;
  const epoch = ++presentationRenderEpoch;
  const artboard = page.artboard || resolvedDeckAppearance(page).artboard || state.artboard;
  const width = Math.max(1, Math.round((Number(artboard.widthIn) || 7.1) * INCH));
  const height = Math.max(1, Math.round((Number(artboard.heightIn) || 5) * INCH));
  presentationCanvasLayout = { width, height };
  staticCanvas.setDimensions({ width, height }, { cssOnly: false });
  staticCanvas.backgroundColor = resolvedDeckAppearance(page).background || "#ffffff";
  const localSnapshot = page.fabric || (page.id === state.deck.activePageId ? stripMasterInheritanceFromSnapshot(canonicalizeLiveBooleanFabricSnapshot(canvas?.toJSON(CUSTOM_PROPS))) : null) || { objects: [] };
  const fabricSnapshot = composeDeckPageSnapshot(page, localSnapshot);
  const result = staticCanvas.loadFromJSON(JSON.parse(JSON.stringify(fabricSnapshot)));
  if (result && typeof result.then === "function") await result;
  if (!presentationState.active || epoch !== presentationRenderEpoch) return false;
  staticCanvas.renderAll();
  if (els.presentationSlideCounter) els.presentationSlideCounter.textContent = `${presentationState.pageIndex + 1} / ${pages.length}`;
  if (els.presentationNotesText) els.presentationNotesText.textContent = speakerNotesForPage(page) || "No speaker notes for this slide.";
  requestAnimationFrame(() => requestAnimationFrame(fitPresentationCanvasToOverlay));
  return true;
}

function exitPresentation(options = {}) {
  if (!presentationState.active) return false;
  presentationRenderEpoch += 1;
  presentationState.active = false;
  presentationState.notesOpen = false;
  presentationCanvasLayout = null;
  if (els.presentationOverlay) els.presentationOverlay.hidden = true;
  els.presentationOverlay?.classList.remove("has-presenter-notes");
  if (els.presentationNotesDrawer) els.presentationNotesDrawer.hidden = true;
  const returnState = presentationState.returnState;
  presentationState.returnState = null;
  if (els.studioShell) {
    els.studioShell.inert = false;
    els.studioShell.removeAttribute("aria-hidden");
  }
  if (returnState) {
    state.view = { ...returnState.view };
    setSidebarTab(returnState.sidebarTab);
    setInspectorTab(returnState.inspectorTab);
    const byId = new Map(canvas?.getObjects?.().map((object) => [object.figureId, object]) || []);
    const selected = returnState.selectedIds.map((id) => byId.get(id)).filter(Boolean);
    if (selected.length) setActiveObjects(selected);
    else canvas?.discardActiveObject();
    updateStage();
    syncUi();
  }
  if (options.restoreFocus !== false) restorePresentationFocus();
  return true;
}

function updateLayoutIdentityInSnapshot(snapshot, masterId, layoutId) {
  const visit = (items) => (items || []).forEach((item) => {
    if (item.figureStudioLayoutPlaceholder) item.figureStudioLayoutPlaceholder = { ...item.figureStudioLayoutPlaceholder, masterId, layoutId };
    if (item.figureStudioLayoutBinding) item.figureStudioLayoutBinding = { ...item.figureStudioLayoutBinding, masterId, layoutId };
    visit(item.objects);
  });
  visit(snapshot?.objects);
  return snapshot;
}

function ensureDeckState() {
  if (!state.deck || !Array.isArray(state.deck.pages)) state.deck = { activePageId: "", themeId: "scientific", layouts: Object.keys(DECK_LAYOUTS), masters: [], pages: [], sections: [], guidePresets: [] };
  if (!DECK_THEMES[state.deck.themeId]) state.deck.themeId = "scientific";
  state.deck.masters = normalizeDeckMasters(state.deck.masters);
  const masterIds = new Set(state.deck.masters.map((master) => master.id));
  state.deck.layouts = Array.from(new Set(state.deck.masters.flatMap((master) => master.layouts.map((layout) => layout.id))));
  (state.deck.pages || []).forEach((page) => {
    const master = masterIds.has(page.masterId)
      ? state.deck.masters.find((item) => item.id === page.masterId)
      : state.deck.masters[0];
    const layout = master.layouts.find((item) => item.id === page.layoutId)
      || master.layouts.find((item) => item.id === "title-content")
      || master.layouts[0];
    page.masterId = master.id;
    page.layoutId = layout?.id || "title-content";
    if (page.fabric) updateLayoutIdentityInSnapshot(page.fabric, page.masterId, page.layoutId);
  });
  if (!state.deck.pages.length && canvas) {
    const page = defaultDeckPage(isPresentationDocument() ? "Slide 1" : "Figure 1");
    state.deck.pages.push(page);
    state.deck.activePageId = page.id;
  }
  if (!state.deck.activePageId && state.deck.pages[0]) state.deck.activePageId = state.deck.pages[0].id;
  state.deck.sections = normalizeDeckSections(state.deck.sections, state.deck.pages);
  state.deck.guidePresets = normalizeDeckGuidePresets(state.deck.guidePresets);
  enforcePresentationDeckGeometry(state.deck);
  return state.deck;
}

function activeDeckPage() {
  ensureDeckState();
  return state.deck.pages.find((page) => page.id === state.deck.activePageId) || state.deck.pages[0] || null;
}

function syncSmartConnectorLabel(connector) {
  if (!isSmartConnectorObject(connector)) return;
  const meta = normalizeSmartConnectorMeta(connector.smartConnectorMeta);
  const label = String(meta.label || "").trim();
  let text = smartConnectorLabelObject(connector);
  if (!label) {
    if (text) canvas.remove(text);
    return;
  }
  if (!text) {
    text = baseMeta(new fabricRef.Text(label, {
      fontSize: 12,
      fill: readStyle(connector).stroke || "#0f766e",
      selectable: true,
      ...(meta.labelPlacement === "midpoint" ? { fontFamily: DEFAULT_FONT_FAMILY } : {})
    }), "connectorLabel", "Connector label", sourceMeta({ kind: "connector-label" }), {});
    text.smartConnectorMeta = { connectorId: connector.figureId };
    canvas.add(text);
  }
  text.set({
    text: label,
    fill: readStyle(connector).stroke || "#0f766e"
  });
  const base = smartConnectorLabelBasePosition(connector, meta, text);
  const offsetOwner = isActiveSelectionObject(connector.group) ? { group: null } : connector;
  const offset = meta.labelPlacement === "midpoint"
    ? smartConnectorLabelOffsetInParent(offsetOwner, text, meta.labelOffset)
    : meta.labelOffset;
  text.set({ left: base.left + offset.x, top: base.top + offset.y });
  text.setCoords?.();
}

function refreshSmartConnectors() {
  if (!canvas) return [];
  const objects = allCanvasObjectsDeep();
  const connectors = objects.filter(isSmartConnectorObject).sort((left, right) => String(left.figureId || "").localeCompare(String(right.figureId || "")));
  const connectorIds = new Set(connectors.map((connector) => connector.figureId).filter(Boolean));
  objects.filter((object) => object.figureType === "connectorLabel" && !connectorIds.has(object.smartConnectorMeta?.connectorId)).forEach((label) => {
    if (label.group?.remove) label.group.remove(label);
    else canvas.remove(label);
  });
  // A bounded settle lets freshly projected peer labels participate in deterministic lane scoring.
  const refreshed = [];
  [0, 1, 2, 3].forEach(() => connectors.forEach((connector) => {
    if (updateSmartConnectorGeometry(connector)) {
      refreshed.push(connector);
      syncSmartConnectorLabel(connector);
    }
  }));
  recordDependencyRefreshForQa("connector", "global", refreshed);
  renderSmartConnectorOverlay();
  return [...new Set(refreshed)];
}
